-- ----------------------------------------------------------------------------
-- Substrates: The three substrates checked against the R0 spec: transparent (the real representation) and two controls, tangled and interpreter, that are expected to fail reflection on purpose.
-- ----------------------------------------------------------------------------
INSERT INTO substrates (substrate_id, description, paper_section_ref, is_control, answer_key_results, reflection_results)
VALUES ('transparent', 'transpile.py emits one function per G_R node: a rule body as explicit nested loops, a non-recursive predicate as the union of its rules, a recursive stratum as a c_mu_* fixed-point driver. runtime.py never reads the spec JSON.', '§12-13', FALSE, NULL, NULL) ON CONFLICT (substrate_id) DO UPDATE SET description = EXCLUDED.description, paper_section_ref = EXCLUDED.paper_section_ref, is_control = EXCLUDED.is_control, answer_key_results = EXCLUDED.answer_key_results, reflection_results = EXCLUDED.reflection_results;

INSERT INTO substrates (substrate_id, description, paper_section_ref, is_control, answer_key_results, reflection_results)
VALUES ('tangled', 'The transparent module with every predicate read inside a rule routed through _dispatch(name, S), which resolves the target by name at run time. Same computation, same answers; dependency preservation and bounded locality fail because dependencies are now strings resolved dynamically.', '§23', TRUE, NULL, NULL) ON CONFLICT (substrate_id) DO UPDATE SET description = EXCLUDED.description, paper_section_ref = EXCLUDED.paper_section_ref, is_control = EXCLUDED.is_control, answer_key_results = EXCLUDED.answer_key_results, reflection_results = EXCLUDED.reflection_results;

INSERT INTO substrates (substrate_id, description, paper_section_ref, is_control, answer_key_results, reflection_results)
VALUES ('interpreter', 'The rulebook loaded as inert JSON and handed to one universal evaluator (the SQLite oracle, compiling at request time). Zero image functions; constructor preservation, dependency preservation and addressability all fail.', '§6, §13', TRUE, NULL, NULL) ON CONFLICT (substrate_id) DO UPDATE SET description = EXCLUDED.description, paper_section_ref = EXCLUDED.paper_section_ref, is_control = EXCLUDED.is_control, answer_key_results = EXCLUDED.answer_key_results, reflection_results = EXCLUDED.reflection_results;

